// Wejście: słowo s. Wyjście: długość najdłuższego palindromu, sam palindrom (najbardziej na lewo)
// i liczba wszystkich podsłów palindromicznych (liczonych z pozycjami).
#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    vector<int> d1(n), d2(n);
    for (int i = 0, l = 0, r = -1; i < n; i++) {          // palindromy nieparzyste
        int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);
        while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) k++;
        d1[i] = k--;
        if (i + k > r) { l = i - k; r = i + k; }
    }
    for (int i = 0, l = 0, r = -1; i < n; i++) {          // palindromy parzyste
        int k = (i > r) ? 0 : min(d2[l + r - i + 1], r - i + 1);
        while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k]) k++;
        d2[i] = k--;
        if (i + k > r) { l = i - k - 1; r = i + k; }
    }
    int bestLen = 0, bestStart = 0;
    long long count = 0;
    for (int i = 0; i < n; i++) {
        count += d1[i] + d2[i];
        if (2 * d1[i] - 1 > bestLen) { bestLen = 2 * d1[i] - 1; bestStart = i - d1[i] + 1; }
        if (2 * d2[i] > bestLen) { bestLen = 2 * d2[i]; bestStart = i - d2[i]; }
    }
    cout << bestLen << "\n" << s.substr(bestStart, bestLen) << "\n" << count << "\n";
}

