// Wejście: słowo s (n do kilku tysięcy). Wyjście: najdłuższy palindrom-podsłowo (najbardziej na lewo),
// liczba podsłów palindromicznych, najdłuższy podciąg palindromiczny, minimalna liczba cięć na palindromy.
#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();

    // 1) rozszerzanie od środka: O(n^2) czasu, O(1) pamięci
    int bestL = 0, bestLen = 1;
    for (int c = 0; c < n; c++)
        for (int even = 0; even <= 1; even++) {
            int l = c, r = c + even;
            while (l >= 0 && r < n && s[l] == s[r]) { l--; r++; }
            int len = r - l - 1;
            if (len > bestLen) { bestLen = len; bestL = l + 1; }
        }

    // 2) is_pal[l][r] i liczba palindromów-podsłów
    vector<vector<char>> pal(n, vector<char>(n, 0));
    long long cnt = 0;
    for (int l = n - 1; l >= 0; l--)
        for (int r = l; r < n; r++) {
            pal[l][r] = (s[l] == s[r]) && (r - l < 2 || pal[l + 1][r - 1]);
            cnt += pal[l][r];
        }

    // 3) najdłuższy podciąg palindromiczny
    vector<vector<int>> lps(n, vector<int>(n, 0));
    for (int l = n - 1; l >= 0; l--) {
        lps[l][l] = 1;
        for (int r = l + 1; r < n; r++)
            lps[l][r] = (s[l] == s[r]) ? lps[l + 1][r - 1] + 2 : max(lps[l + 1][r], lps[l][r - 1]);
    }

    // 4) minimalna liczba cięć: cut[j] = min cięć dla s[0..j]
    vector<int> cut(n, INT_MAX);
    for (int j = 0; j < n; j++)
        for (int i = 0; i <= j; i++)
            if (pal[i][j]) cut[j] = min(cut[j], i == 0 ? 0 : cut[i - 1] + 1);

    cout << s.substr(bestL, bestLen) << "\n" << cnt << "\n" << lps[0][n - 1] << "\n" << cut[n - 1] << "\n";
}

