// Wejście: słowo s. Wyjście: tablica sufiksowa (od 0), tablica LCP, liczba różnych podsłów.
#include <bits/stdc++.h>
using namespace std;

vector<int> suffixArray(string s) {
    s += char(0);
    int n = s.size();
    const int ALPHA = 256;
    vector<int> p(n), c(n), cnt(max(ALPHA, n), 0);
    for (int i = 0; i < n; i++) cnt[(unsigned char)s[i]]++;
    for (int i = 1; i < ALPHA; i++) cnt[i] += cnt[i - 1];
    for (int i = 0; i < n; i++) p[--cnt[(unsigned char)s[i]]] = i;
    c[p[0]] = 0;
    int classes = 1;
    for (int i = 1; i < n; i++) {
        if (s[p[i]] != s[p[i - 1]]) classes++;
        c[p[i]] = classes - 1;
    }
    vector<int> pn(n), cn(n);
    for (int h = 0; (1 << h) < n; h++) {
        for (int i = 0; i < n; i++) {
            pn[i] = p[i] - (1 << h);
            if (pn[i] < 0) pn[i] += n;
        }
        fill(cnt.begin(), cnt.begin() + classes, 0);
        for (int i = 0; i < n; i++) cnt[c[pn[i]]]++;
        for (int i = 1; i < classes; i++) cnt[i] += cnt[i - 1];
        for (int i = n - 1; i >= 0; i--) p[--cnt[c[pn[i]]]] = pn[i];
        cn[p[0]] = 0;
        classes = 1;
        for (int i = 1; i < n; i++) {
            pair<int, int> cur = {c[p[i]], c[(p[i] + (1 << h)) % n]};
            pair<int, int> prev = {c[p[i - 1]], c[(p[i - 1] + (1 << h)) % n]};
            if (cur != prev) classes++;
            cn[p[i]] = classes - 1;
        }
        c.swap(cn);
        if (classes == n) break;
    }
    p.erase(p.begin());
    return p;
}

vector<int> lcpKasai(const string& s, const vector<int>& sa) {
    int n = s.size();
    vector<int> rk(n), lcp(max(n - 1, 0), 0);
    for (int i = 0; i < n; i++) rk[sa[i]] = i;
    for (int i = 0, k = 0; i < n; i++) {
        if (rk[i] == n - 1) { k = 0; continue; }
        int j = sa[rk[i] + 1];
        while (i + k < n && j + k < n && s[i + k] == s[j + k]) k++;
        lcp[rk[i]] = k;
        if (k > 0) k--;
    }
    return lcp;
}

int main() {
    string s;
    cin >> s;
    vector<int> sa = suffixArray(s);
    vector<int> lcp = lcpKasai(s, sa);
    long long n = s.size(), distinct = n * (n + 1) / 2;
    for (int x : lcp) distinct -= x;
    for (int x : sa) cout << x << " ";
    cout << "\n";
    for (int x : lcp) cout << x << " ";
    cout << "\n" << distinct << "\n";
}

