// Wejście: k, potem k wzorców (małe litery), potem tekst. Wyjście: liczba wystąpień każdego wzorca.
#include <bits/stdc++.h>
using namespace std;

struct AhoCorasick {
    vector<array<int, 26>> go;
    vector<int> fail, order;
    AhoCorasick() { addNode(); }
    int addNode() {
        go.emplace_back();
        go.back().fill(-1);
        fail.push_back(0);
        return go.size() - 1;
    }
    int insert(const string& p) {
        int v = 0;
        for (char ch : p) {
            int c = ch - 'a';
            if (go[v][c] == -1) { int u = addNode(); go[v][c] = u; }
            v = go[v][c];
        }
        return v;
    }
    void build() {
        queue<int> q;
        for (int c = 0; c < 26; c++) {
            if (go[0][c] == -1) go[0][c] = 0;
            else { fail[go[0][c]] = 0; q.push(go[0][c]); }
        }
        while (!q.empty()) {
            int v = q.front(); q.pop();
            order.push_back(v);
            for (int c = 0; c < 26; c++) {
                int u = go[v][c];
                if (u == -1) go[v][c] = go[fail[v]][c];
                else { fail[u] = go[fail[v]][c]; q.push(u); }
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int k;
    cin >> k;
    AhoCorasick ac;
    vector<int> endNode(k);
    for (int i = 0; i < k; i++) {
        string p;
        cin >> p;
        endNode[i] = ac.insert(p);
    }
    ac.build();
