    vector<int> fail, order;                 // link sufiksowy, węzły w kolejności BFS
    AhoCorasick() { addNode(); }             // węzeł 0 = korzeń
    int addNode() {
        go.emplace_back();
        go.back().fill(-1);
        fail.push_back(0);
        return go.size() - 1;
