        int v = 0;
        for (char ch : p) {
            int c = ch - 'a';
            if (go[v][c] == -1) { int u = addNode(); go[v][c] = u; }
            v = go[v][c];
        }
        return v;
    }
    void build() {
        queue<int> q;
        for (int c = 0; c < 26; c++) {
            if (go[0][c] == -1) go[0][c] = 0;
            else { fail[go[0][c]] = 0; q.push(go[0][c]); }
        }
        while (!q.empty()) {
            int v = q.front(); q.pop();
            order.push_back(v);
            for (int c = 0; c < 26; c++) {
                int u = go[v][c];
                if (u == -1) go[v][c] = go[fail[v]][c];          // brak krawędzi: przejście jak z linku
                else { fail[u] = go[fail[v]][c]; q.push(u); }    // link dziecka
            }
        }
    }
};

           long long countGood(const vector<string>& pats, int L, int alpha) {   // słowa nad 'a'..'a'+alpha-1
               const long long MOD = 1'000'000'007;
               AhoCorasick ac;
               vector<int> ends;
               for (auto& p : pats) ends.push_back(ac.insert(p));
               ac.build();
               int S = ac.go.size();
               vector<char> bad(S, 0);
               for (int e : ends) bad[e] = 1;
               for (int v : ac.order) bad[v] |= bad[ac.fail[v]];
               vector<long long> dp(S, 0), nd(S);
               dp[0] = 1;
               for (int i = 0; i < L; i++) {
                   fill(nd.begin(), nd.end(), 0);
                   for (int v = 0; v < S; v++) if (dp[v] && !bad[v])
                       for (int c = 0; c < alpha; c++) {
                           int u = ac.go[v][c];
                           if (!bad[u]) nd[u] = (nd[u] + dp[v]) % MOD;
                       }
                   swap(dp, nd);
               }
               long long res = 0;
               for (int v = 0; v < S; v++) if (!bad[v]) res = (res + dp[v]) % MOD;
               return res;
           }

