// Operacje: "+ w" wstaw, "- w" usuń jedno wystąpienie, "? w" czy jest (TAK/NIE), "# p" ile słów ma prefiks p.
#include <bits/stdc++.h>
using namespace std;

struct Trie {
    vector<array<int, 26>> nxt;
    vector<int> pass, ends;
    Trie() { addNode(); }
    int addNode() {
        nxt.emplace_back();
        nxt.back().fill(0);
        pass.push_back(0);
        ends.push_back(0);
        return nxt.size() - 1;
    }
    void insert(const string& w) {
        int v = 0;
        pass[v]++;
        for (char ch : w) {
            int c = ch - 'a';
            if (!nxt[v][c]) { int u = addNode(); nxt[v][c] = u; }
            v = nxt[v][c];
            pass[v]++;
        }
        ends[v]++;
    }
    int walk(const string& w) const {
        int v = 0;
        for (char ch : w) {
            v = nxt[v][ch - 'a'];
            if (!v) return -1;
        }
        return v;
    }
    bool contains(const string& w) const { int v = walk(w); return v != -1 && ends[v] > 0; }
    int countPrefix(const string& p) const { int v = walk(p); return v == -1 ? 0 : pass[v]; }
    void erase(const string& w) {
        if (!contains(w)) return;
        int v = 0;
        pass[v]--;
        for (char ch : w) { v = nxt[v][ch - 'a']; pass[v]--; }
        ends[v]--;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    Trie t;
    while (q--) {
        char op;
        string w;
        cin >> op >> w;
        if (op == '+') t.insert(w);
        else if (op == '-') t.erase(w);
        else if (op == '?') cout << (t.contains(w) ? "TAK" : "NIE") << "\n";
        else cout << t.countPrefix(w) << "\n";
    }
}

struct XorTrie {
    static const int B = 30;                 // liczby z zakresu [0, 2^31)
    vector<array<int, 2>> nx;
    XorTrie() { nx.push_back({0, 0}); }
    void insert(int x) {
        int v = 0;
        for (int b = B; b >= 0; b--) {
            int bit = (x >> b) & 1;
            if (!nx[v][bit]) { int u = nx.size(); nx.push_back({0, 0}); nx[v][bit] = u; }
            v = nx[v][bit];
        }
    }
    int maxXor(int x) const {                // max x ^ y po y w trie (trie niepuste)
        int v = 0, r = 0;
        for (int b = B; b >= 0; b--) {
            int bit = (x >> b) & 1;
            if (nx[v][bit ^ 1]) { r |= 1 << b; v = nx[v][bit ^ 1]; }   // zachłannie: przeciwny bit daje 1
            else v = nx[v][bit];
        }
        return r;
    }
};

